/**
 * Derives a brand logo id from a model id / name, independent of the
 * hosting provider. Used for the Model breakdown so `deepseek-v4-pro`
 * hosted via `opencode` still shows the DeepSeek whale, not the
 * OpenCode square.
 */
export function modelLogoId(model: string | null | undefined): string | null {
  const raw = (model ?? "").toLowerCase().trim();
  if (!raw) return null;
  // Strip provider prefix like "openai/gpt-5.5" or "zai/glm-5.2"
  const slash = raw.lastIndexOf("/");
  const base = slash >= 0 ? raw.slice(slash + 1) : raw;
  // Also strip any leading provider prefix with colon
  const normalized = base.split(":")[0] ?? base;

  if (normalized.startsWith("deepseek")) return "deepseek";
  if (normalized.startsWith("kimi") || normalized.startsWith("moonshot")) return "moonshot";
  if (normalized.startsWith("claude")) return "claude";
  if (normalized.startsWith("gpt") || normalized.startsWith("o1") || normalized.startsWith("o3") || normalized.startsWith("o4") || normalized.startsWith("codex")) return "codex";
  if (normalized.startsWith("grok")) return "grok";
  if (normalized.startsWith("gemini") || normalized.startsWith("gemma")) return "google";
  if (normalized.startsWith("glm") || normalized.startsWith("zai")) return "zai";
  if (normalized.startsWith("mistral") || normalized.startsWith("mixtral") || normalized.startsWith("codestral") || normalized.startsWith("ministral")) return "mistral";
  if (normalized.startsWith("minimax") || normalized.startsWith("minimaxi")) return "minimax";
  if (normalized.startsWith("mimo") || normalized.startsWith("xiaomi")) return "mimo";
  if (normalized.startsWith("muse")) return "muse";
  if (normalized.startsWith("llama") || normalized.startsWith("meta-llama")) return "meta";
  if (normalized.startsWith("copilot")) return "copilot";
  // Fallback: try first token before -/_ as provider id
  const prefix = normalized.split(/[-_]/)[0] ?? "";
  if (prefix && (LOGOS[prefix] || LOGO_ALIASES[prefix])) return prefix;
  return null;
}

function specFor(id: string | null | undefined): LogoSpec | null {
  const key = (id ?? "").toLowerCase().trim();
  if (!key) return null;
  return LOGOS[key] ?? LOGOS[LOGO_ALIASES[key] ?? ""] ?? null;
}

const LOGO_SIZES = {
  sm: { pixels: 15, className: "size-[15px]" },
  md: { pixels: 17, className: "size-[17px]" },
  lg: { pixels: 22, className: "size-[22px]" },
} as const;

export type ProviderLogoSize = keyof typeof LOGO_SIZES;

export function ProviderLogo({
  id,
  size = "md",
  className,
}: {
  id: string | null | undefined;
  name?: string;
  size?: ProviderLogoSize;
  className?: string;
}) {
  const spec = specFor(id);
  if (!spec) return null;
  const logoSize = LOGO_SIZES[size];
  return (
    <svg
      viewBox={spec.viewBox ?? "0 0 24 24"}
      width={logoSize.pixels}
      height={logoSize.pixels}
      aria-hidden="true"
      className={cn("shrink-0 select-none", logoSize.className, className)}
    >
      {spec.layers.map((layer, index) => (
        <path key={index} d={layer.d} fill={layer.fill ?? spec.color ?? "currentColor"} fillRule={layer.fillRule} />
      ))}
    </svg>
  );
}
